package com.shazwan.idash;
import android.app.*;import android.content.*;import android.os.*;import android.provider.*;import android.view.*;import android.widget.*;
/** Public intents, DND controls. No foreground/background service. */
final class ControlUtilities {
 final LauncherActivity a;final QuickControls q;final NotificationManager notifications;final Handler main=new Handler(Looper.getMainLooper());
 AlertDialog prompt;View focus;TextView focusStatus;View[] buttons=new View[3];Intent timer,calculator;boolean active,receiverRegistered;int generation;
 ControlUtilities(LauncherActivity a,QuickControls q){this.a=a;this.q=q;notifications=(NotificationManager)a.getSystemService(Context.NOTIFICATION_SERVICE);}
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){renderFocus();}};
 @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag") void resume(){if(active)return;active=true;int current=++generation;IntentFilter filter=new IntentFilter(NotificationManager.ACTION_INTERRUPTION_FILTER_CHANGED);filter.addAction(NotificationManager.ACTION_NOTIFICATION_POLICY_ACCESS_GRANTED_CHANGED);if(Build.VERSION.SDK_INT>=33)a.registerReceiver(receiver,filter,Context.RECEIVER_EXPORTED);else a.registerReceiver(receiver,filter);receiverRegistered=true;resolveApps();renderFocus();renderButtons();
  // Queue behind launcher discovery so the existing Calculator fallback sees the loaded app list.
  a.worker.execute(()->main.post(()->{if(!active||generation!=current||a.destroyed)return;resolveApps();renderButtons();}));
 }
 void pause(){if(prompt!=null){prompt.dismiss();prompt=null;}active=false;generation++;if(receiverRegistered){receiverRegistered=false;try{a.unregisterReceiver(receiver);}catch(IllegalArgumentException ignored){}}}
 Intent supported(Intent intent){return intent.resolveActivity(a.getPackageManager())!=null?intent:null;}
 void resolveApps(){timer=supported(new Intent(AlarmClock.ACTION_SHOW_TIMERS));if(timer==null)timer=supported(new Intent(AlarmClock.ACTION_SET_TIMER));calculator=supported(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_APP_CALCULATOR));if(calculator==null)for(LauncherActivity.App app:a.apps)if(app.label.toLowerCase(java.util.Locale.ROOT).contains("calculator")||app.label.toLowerCase(java.util.Locale.ROOT).contains("kalkulator")){calculator=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(ComponentName.unflattenFromString(app.component));break;}}
 void set(View v,String label,boolean enabled,String detail){if(v==null)return;v.setEnabled(enabled);v.setAlpha(enabled?1:IosStyle.CC_DISABLED_ALPHA);v.setContentDescription(label+" · "+detail);if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;if(g.getChildCount()>1&&g.getChildAt(1) instanceof TextView)((TextView)g.getChildAt(1)).setText(label);}}
 void renderButtons(){if(buttons[0]==null)return;set(buttons[0],"Settings",true,"Open Android Settings");set(buttons[1],timer==null?"No timer":"Timer",timer!=null,"Open timer app");set(buttons[2],calculator==null?(!a.loaded?"Checking…":"No calculator"):"Calculator",calculator!=null,"Open calculator app");}
 void renderFocus(){if(focusStatus==null)return;try{boolean available=notifications!=null;int state=available?notifications.getCurrentInterruptionFilter():NotificationManager.INTERRUPTION_FILTER_UNKNOWN;focus.setEnabled(available&&state!=0);focus.setAlpha(available&&state!=0?1:IosStyle.CC_DISABLED_ALPHA);focusStatus.setText(!available||state==0?"Unavailable":!notifications.isNotificationPolicyAccessGranted()?"Access needed":state==NotificationManager.INTERRUPTION_FILTER_ALL?"Off":state==NotificationManager.INTERRUPTION_FILTER_PRIORITY?"Priority":state==NotificationManager.INTERRUPTION_FILTER_ALARMS?"Alarms only":"Total silence");focus.setContentDescription("Focus · "+focusStatus.getText());}catch(RuntimeException denied){focusStatus.setText("Unavailable");}}
 boolean policyGranted(){try{return notifications!=null&&notifications.isNotificationPolicyAccessGranted();}catch(RuntimeException unsupported){return false;}}
 void focus(){if(notifications==null)return;if(!policyGranted()){prompt=new AlertDialog.Builder(a).setTitle("Focus / Do Not Disturb").setMessage("Notification Policy Access lets iDash change Android's Do Not Disturb filter when you choose a mode. Nothing is changed by opening this panel.").setNegativeButton("Cancel",null).setPositiveButton("Open access settings",(d,w)->a.openSettings(Settings.ACTION_NOTIFICATION_POLICY_ACCESS_SETTINGS)).show();return;}prompt=new AlertDialog.Builder(a).setTitle("Focus / Do Not Disturb").setItems(new String[]{"Off","Priority only","Alarms only"},(d,index)->{try{notifications.setInterruptionFilter(new int[]{NotificationManager.INTERRUPTION_FILTER_ALL,NotificationManager.INTERRUPTION_FILTER_PRIORITY,NotificationManager.INTERRUPTION_FILTER_ALARMS}[index]);}catch(RuntimeException denied){Toast.makeText(a,"DND change unavailable on this device",Toast.LENGTH_SHORT).show();}renderFocus();}).setNegativeButton("Cancel",null).show();}
 void launch(Intent intent){if(intent==null){Toast.makeText(a,"No compatible app installed",Toast.LENGTH_SHORT).show();return;}try{a.startActivity(intent);}catch(ActivityNotFoundException|SecurityException unavailable){Toast.makeText(a,"App unavailable or access denied",Toast.LENGTH_SHORT).show();resolveApps();renderButtons();}}
 void click(int index){if(index==0){q.close();a.openSettings(Settings.ACTION_SETTINGS);}else launch(index==1?timer:calculator);}
}
